    // === Session 2026-04-18 Step 3 Tier 1: public page strings ===
    about_our_approach: 'Notre approche',
    about_our_mission: 'Notre mission',
    about_start_in_minutes: 'Commencez en quelques minutes',
    about_the_problem: 'Le problème',
    about_what_we_stand_for: 'Nos valeurs',
    about_back_home: 'Retour à l\'accueil',
    about_hero_1: 'La maîtrise du SaaS,',
    about_hero_2: 'pour tous les autres.',
    about_hero_sub: 'Une gestion SaaS de niveau entreprise, conçue pour les PME européennes qui ne peuvent pas justifier 30 000 € par an pour la visibilité de leurs logiciels.',
    about_problem_p1: 'Une entreprise type de 100 personnes paie aujourd\'hui plus de 80 outils SaaS. Des licences sont oubliées. Des employés partent en conservant leur accès. Des contrats se renouvellent automatiquement à des tarifs gonflés. Dans la plupart des organisations, personne n\'a la vue d\'ensemble — et le coût de cette confusion est bien réel.',
    about_problem_p2: 'Les outils qui résolvent ce problème à l\'échelle des grandes entreprises — Zylo, Torii, Lumos — sont excellents. Ils facturent aussi entre 30 000 et 50 000 € par an et nécessitent des équipes d\'achats dédiées. Cela laisse à toute entreprise de moins de 500 employés deux options : payer pour le chaos, ou embaucher quelqu\'un à temps plein pour le gérer.',
    about_approach_p1: 'Stacklens est la troisième option. Nous proposons les 80 % essentiels de la gestion SaaS d\'entreprise — visibilité, détection du gaspillage, alertes de renouvellement, analyse de contrats — conçus spécifiquement pour les PME européennes.',
    about_approach_p2: 'Tarification transparente dès 29 € par mois. Hébergé en Europe. Conçu pour le RGPD. Aucun engagement annuel. Aucun appel commercial. Une mission claire : donner à chaque PME la maîtrise du SaaS autrefois réservée aux grandes entreprises du Fortune 500.',
    about_principle1_title: 'Tarification transparente',
    about_principle1_body: 'Des forfaits publics, sans palier « contacter les ventes ». Vous voyez le prix avant de vous inscrire — y compris au niveau entreprise.',
    about_principle2_title: 'Européen par conception',
    about_principle2_body: 'Hébergé en Europe. Conçu pour le RGPD dès le premier jour. Pensé pour le contexte réglementaire et linguistique des PME européennes.',
    about_principle3_title: 'Périmètre ciblé',
    about_principle3_body: 'Nous proposons les 80 % de la gestion SaaS qui comptent le plus. Nous ne cherchons pas à être une suite RH, un système de tickets IT ou une plateforme SCIM/PAM.',
    about_principle4_title: 'Support accessible',
    about_principle4_body: 'Communication directe avec l\'équipe qui développe le produit. Aucune file de niveau 1, aucun SLA de 48 heures.',
