    lp_who_subtitle: 'Vous ne vous êtes pas inscrit pour gérer plus de 80 outils SaaS. Mais quelqu\'un doit relancer les renouvellements, nettoyer les comptes fantômes et répondre à « combien dépensons-nous en logiciels ? » — et ce quelqu\'un, c\'est vous.',
