    lp_feat_api_access: 'Accès API',
    lp_feat_dedicated_support: 'Support dédié',
    lp_pricing_footnote: 'Forfait gratuit disponible dès maintenant. Les forfaits payants incluent l\'hébergement des données en Europe, la conformité RGPD et des analyses de contrats illimitées.',
    lp_faq_q1: 'En quoi est-ce différent de Zylo, Torii ou Lumos ?',
    lp_faq_a1: 'Ce sont d\'excellents produits conçus pour les grandes entreprises disposant de budgets de 30 à 50 K€ et d\'équipes d\'achats dédiées. Stacklens couvre les 80 % essentiels — visibilité, détection du gaspillage, alertes de renouvellement — à 1/20e du prix. Nous ne faisons pas de SCIM ni de PAM. Si vous en avez besoin, adressez-vous à eux. Si vous voulez simplement voir pour quoi vous payez, parlez-nous.',
    lp_faq_q2: 'Où sont stockées mes données ?',
    lp_faq_a2: 'Google Cloud, europe-west1 (Belgique). Vos données ne quittent jamais l\'UE. Chaque client dispose de bases Firestore isolées — aucune infrastructure partagée. Conçu pour le RGPD, et non adapté après coup.',
    lp_faq_q3: 'Dois-je vous donner un accès administrateur à mon Google Workspace ?',
    lp_faq_a3: 'Non. L\'import CSV fonctionne pour tout. La synchronisation administrateur basée sur OAuth est optionnelle et prévue pour le T2 2026. Pour l\'instant, vous pouvez coller une liste d\'outils manuellement ou importer un CSV depuis votre système comptable.',
    lp_faq_q4: 'Ai-je besoin d\'une carte bancaire pour l\'essayer ?',
    lp_faq_a4: 'Non. Le forfait gratuit ne nécessite aucune carte bancaire et reste gratuit à vie pour les petites équipes. Les forfaits payants offrent des essais de 7 jours sans carte bancaire au préalable.',
    lp_faq_q5: 'Combien de temps prend la configuration ?',
    lp_faq_a5: 'Environ 5 minutes. Inscrivez-vous, importez un CSV (ou ajoutez quelques outils manuellement), invitez votre équipe. La plupart des clients identifient leur première opportunité d\'économie en moins de 10 minutes.',
    lp_faq_q6: 'Et si je veux résilier ?',
    lp_faq_a6: 'Cliquez sur « Résilier l\'abonnement » dans les Paramètres. Aucun email de rétention. Aucune fenêtre « êtes-vous sûr ? ». Vos données restent accessibles pendant 30 jours, puis sont supprimées.',
    lp_final_subtitle: 'Gratuit à vie jusqu\'à 10 outils. Sans carte bancaire. Sans appel de démonstration. Inscrivez-vous et commencez.',
    lp_final_cta: 'Créer mon compte gratuit',
