    lp_feat_api_access: 'Accès API',
    lp_feat_dedicated_support: 'Support dédié',
    lp_pricing_footnote: 'Forfait gratuit disponible dès maintenant. Les forfaits payants incluent l\'hébergement des données en UE, la conformité RGPD et des analyses de contrats illimitées.',
    lp_faq_q1: 'En quoi est-ce différent de Zylo, Torii ou Lumos ?',
    lp_faq_a1: 'Ce sont d\'excellents produits conçus pour les grandes entreprises disposant de budgets de 30 à 50 k€ et d\'équipes achats dédiées. Stacklens couvre les 80 % essentiels — visibilité, détection du gaspillage, alertes de renouvellement — pour 1/20e du prix. Nous ne proposons ni SCIM ni PAM. Si vous en avez besoin, adressez-vous à eux. Si vous voulez simplement voir ce que vous payez, parlez-nous.',
    lp_faq_q2: 'Où mes données sont-elles stockées ?',
    lp_faq_a2: 'Google Cloud, europe-west1 (Belgique). Vos données ne quittent jamais l\'UE. Chaque client dispose de bases Firestore isolées — aucune infrastructure partagée. RGPD natif, et non ajouté après coup.',
    lp_faq_q3: 'Dois-je vous donner un accès admin à mon Google Workspace ?',
    lp_faq_a3: 'Non. L\'import CSV fonctionne pour tout. La synchronisation admin via OAuth est optionnelle et arrive au T2 2026. Pour l\'instant, vous pouvez coller une liste d\'outils manuellement ou téléverser un CSV depuis votre système comptable.',
    lp_faq_q4: 'Ai-je besoin d\'une carte bancaire pour l\'essayer ?',
    lp_faq_a4: 'Non. Le forfait gratuit ne nécessite aucune carte bancaire et dure indéfiniment pour les petites équipes. Les forfaits payants offrent des essais de 7 jours sans carte bancaire au préalable.',
    lp_faq_q5: 'Combien de temps prend la configuration ?',
    lp_faq_a5: 'Environ 5 minutes. Inscrivez-vous, téléversez un CSV (ou ajoutez quelques outils manuellement), invitez votre équipe. La plupart des clients voient leur première opportunité d\'économies en moins de 10 minutes.',
    lp_faq_q6: 'Et si je veux annuler ?',
    lp_faq_a6: 'Cliquez sur « Annuler l\'abonnement » dans les Paramètres. Aucun e-mail de rétention. Aucune boîte de dialogue « êtes-vous sûr ? ». Vos données restent accessibles pendant 30 jours, puis sont supprimées.',
    lp_final_subtitle: 'Gratuit pour toujours jusqu\'à 10 outils. Sans carte bancaire. Sans appel de démo. Inscrivez-vous et commencez.',
    lp_final_cta: 'Créer mon compte gratuit',
    lp_final_note: 'Essai de 7 jours des fonctionnalités Pro inclus. Rétrogradez à tout moment.',
